public class Solution {
    public String fizzBuzz(int n) {
        // magic numbers everywhere, single-letter vars
        StringBuilder b = new StringBuilder();
        for (int x = 1; x <= n; x++) { if (x > 1) b.append('\n'); if (x % 3 == 0 && x % 5 == 0) b.append("FizzBuzz"); else if (x % 3 == 0) b.append("Fizz"); else if (x % 5 == 0) b.append("Buzz"); else b.append(x); }
        return b.toString();
    }
}
